"""Paired interior selection cuts on complete original editable Streets.

The two trims have reciprocal span owners at one original Section seam.
Only the rendered spans split; source controls, Street IDs and profile law do not.
"""
import hashlib
import bpy
from . import curved_junction_nodes as boundary
from .curved_network_ownership_nodes import _compare

c=boundary.c


def paired_endpoint(g,sources,mapping,span,side):
    other='end' if side=='start' else 'start'
    read=lambda key,at=span,kind='INT':c._read(g,mapping,'st_ps_'+key,at,kind)
    peer=read(side+'_clip_peer')
    valid=_compare(g,peer,0,'GREATER_EQUAL')*_compare(g,peer,c._count(g,mapping),'LESS_THAN')
    valid=valid*(1.-_compare(g,peer,span))*_compare(g,read(other+'_clip_peer',peer),span)
    for key in ('street_id','start','edge_start','count'):
        valid=valid*_compare(g,read(key),read(key,peer))
    valid=valid*_compare(g,read(other+'_role',peer),6)
    valid=valid*g.math('GREATER_THAN',read(other+'_clip',peer,'FLOAT'),0.)
    knot=read('first' if side=='start' else 'last')
    valid=valid*_compare(g,knot,read('last' if side=='start' else 'first',peer))
    valid=valid*_compare(g,knot,0,'GREATER_THAN')*_compare(g,knot,read('count')-1.,'LESS_THAN')
    # The peer must really address the neighboring Section's original edge.
    edge=read('edge_start')+knot-(1. if side=='start' else 0.)
    section=boundary._edge_sample(g,sources,c.named(g,'st_section_id','INT'),edge,'INT')
    street=boundary._edge_sample(g,sources,c.named(g,'st_street_id','INT'),edge,'INT')
    valid=valid*_compare(g,street,read('street_id'))
    valid=valid*_compare(g,section,read('last_section' if side=='start' else 'first_section',peer))
    valid=valid*(1.-_compare(g,section,read('first_section' if side=='start' else 'last_section')))
    for key,kind in ((side+'_clip_peer','INT'),(other+'_clip_peer','INT'),
                     (other+'_role','INT'),(other+'_clip','FLOAT')):
        attr=g.node('GeometryNodeInputNamedAttribute');attr.data_type=kind
        attr.inputs['Name'].default_value='st_ps_'+key
        valid=valid*c._stat(g,mapping,attr.outputs['Exists'])
    return valid


def replace_saved(roots):
    """Extend all four plain/dimensional cut consumers and their builder refs."""
    from . import curved_approach_nodes as approaches,curved_standalone_nodes as runs
    from .curved_quad_fair_nodes import assign_group
    memo={};visiting=set();copies=[];changes=[]
    def visit(tree):
        if tree in memo:return memo[tree]
        if tree in visiting:raise ValueError('Cycle in paired selection builder references')
        if tree.get('st_interior_selection_cuts'):raise ValueError('Interior cut policy already installed')
        visiting.add(tree)
        primitive=tree.get('st_selection_boundaries')==1
        dimensions='Declared dimensional transitions' in tree.name
        if primitive and tree.name.startswith('Prochitecture Streets / Original curved one-ended approach v1'):
            result=approaches.build(local_frames='Local mouth frames' in tree.name,port_paths=True,
                interpolation=True,selection_cuts=True,dimensions=dimensions,interior_cuts=True)
            changes.append(dict(original=tree.name,replacement=result.name,kind='APPROACH',dimensions=dimensions))
        elif primitive and tree.name.startswith('Prochitecture Streets / Category-bounded profiled run v1'):
            result=runs.street(boundary_span=True,interpolation=True,selection_cuts=True,
                               dimensions=dimensions,interior_cuts=True)
            changes.append(dict(original=tree.name,replacement=result.name,kind='BOUNDARY_RUN',dimensions=dimensions))
        else:
            children=[(n.name,visit(n.node_tree)) for n in tree.nodes if n.type=='GROUP' and n.node_tree]
            children=[(name,child) for name,child in children if child!=tree.nodes[name].node_tree]
            refs=[(key,visit(value)) for key,value in tree.items() if isinstance(value,bpy.types.NodeTree)]
            refs=[(key,value) for key,value in refs if value!=tree[key]]
            result=tree.copy() if children or refs else tree
            if result!=tree:
                result.use_fake_user=False;copies.append((tree,result))
                for name,child in children:assign_group(result.nodes[name],child)
                for key,value in refs:result[key]=value
        visiting.remove(tree);memo[tree]=result;return result
    results=[visit(tree) for tree in roots]
    if {(r['kind'],r['dimensions']) for r in changes}!={
            ('APPROACH',False),('APPROACH',True),('BOUNDARY_RUN',False),('BOUNDARY_RUN',True)} or len(changes)!=4:
        raise ValueError('Expected four plain/dimensional selection consumers')
    for old,new in copies:
        name=old.name;old.name='Before paired selection builder / '+hashlib.sha256(name.encode()).hexdigest()[:16]
        new.name=name
        if new.name!=name:raise ValueError('Lost canonical builder entry point')
    return results,changes
